[**Sample EWMA plot**]{#sec-pmc-324-plot}

The control chart is given below.


::: {.cell}

```{.r .cell-code  code-fold="true"}
s_ewma <- sqrt(lambda / (2 - lambda)) * s
ucl <- ewma0 + 3 * s_ewma
lcl <- ewma0 - 3 * s_ewma

ggplot(ewma_df, aes(observation)) +
  geom_hline(yintercept = c(ucl, lcl)) +
  geom_line(aes(y = ewma), color = "forestgreen") +
  geom_point(aes(y = ewma), shape = 0, color = "forestgreen") +
  geom_point(aes(y = y), shape = 4, color = "firebrick") +
  annotate("text", x = 20.5, y = ucl, label = "Upper EWMA Limit", color = "steelblue", hjust = 0, fontface = "bold") +
  annotate("text", x = 20.5, y = lcl, label = "Lower EWMA Limit", color = "navy", hjust = 0) +
  scale_x_continuous(breaks = seq(0, 20, 5)) +
  coord_cartesian(xlim = c(0, 25), ylim = c(min(y), max(y)), clip = "off") +
  labs(title = "EWMA Plot", x = "Observation Number", y = NULL) +
  theme_light() +
  theme(plot.margin = margin(5.5, 90, 5.5, 5.5))
